// Helper function to find workout by exact match
export function findWorkout(target, level, goal, duration) {
  return fitnessWorkoutDatabase.find(w => 
    w.target === target && 
    w.level === level && 
    w.goal === goal && 
    w.duration === duration
  );
}

// Helper to parse workout string into exercises
export function parseWorkoutIntoExercises(workoutString) {
  if (!workoutString) return [];
  
  const exercises = workoutString.split('|').map((ex, idx) => {
    const trimmed = ex.trim();
    const parts = trimmed.split('—');
    const name = parts[0]?.trim();
    const details = parts[1]?.trim() || '';
    
    // Parse sets and reps from details
    let sets = 3;
    let reps = 10;
    let restSeconds = 60;
    
    if (details.includes('AMRAP')) {
      sets = 1;
      reps = 'AMRAP';
      restSeconds = 0;
    } else if (details.includes('x')) {
      const match = details.match(/(\d+)x(\d+)-?(\d+)?/);
      if (match) {
        sets = parseInt(match[1]);
        reps = match[3] ? `${match[2]}-${match[3]}` : match[2];
      }
    } else if (details.includes('rounds')) {
      const match = details.match(/(\d+)\s*rounds/);
      if (match) {
        sets = parseInt(match[1]);
        reps = '30-45s';
        restSeconds = 30;
      }
    }
    
    return {
      id: `ex_${idx}`,
      name: name,
      instructions: details,
      sets: typeof sets === 'number' ? sets : 3,
      reps: reps,
      rest_seconds: restSeconds
    };
  });
  
  return exercises;
}